// @vitest-environment node
/**
 * Unit tests for PDF link extraction.
 * Fixtures are generated by tests/fixtures/generate-pdfs.py.
 */

import { describe, test, expect, beforeAll } from 'vitest';
import { readFile } from 'fs/promises';
import { join } from 'path';
import {
  extractLinksFromPDF,
  PdfExtractionError,
  type ExtractedLink,
} from '@/lib/extractors/pdf';

const fixture = (name: string) => readFile(join(__dirname, '../fixtures', name));

describe('PDF Link Extractor', () => {
  let links: ExtractedLink[];
  const byUrl = (url: string) => links.find((l) => l.url === url);

  beforeAll(async () => {
    links = await extractLinksFromPDF(await fixture('sample.pdf'));
  });

  describe('Link annotations', () => {
    test('uses the text under the clickable area as anchor text', () => {
      expect(byUrl('https://archive.org/web')).toMatchObject({
        originalUrl: 'https://archive.org/web/',
        text: 'the Internet Archive',
        position: { page: 1 },
      });
    });

    test('normalizes annotation URLs (tracking params removed)', () => {
      expect(byUrl('https://example.com/page?page=2')).toMatchObject({
        originalUrl: 'https://example.com/page?utm_source=pdf&page=2',
        text: 'tracked link',
      });
    });

    test('skips mailto: annotations', () => {
      expect(links.some((l) => /mailto:|author@example\.com/.test(l.url))).toBe(false);
    });
  });

  describe('Plain-text URLs', () => {
    test('finds URLs printed in the text', () => {
      expect(byUrl('https://plain.example.com/article')).toMatchObject({
        text: 'https://plain.example.com/article',
        position: { page: 1 },
      });
    });

    test('trims trailing sentence punctuation', () => {
      const link = byUrl('https://journal.example.org/articles/link-rot');
      expect(link?.originalUrl).toBe('https://journal.example.org/articles/link-rot');
    });

    test('trims an unbalanced closing parenthesis', () => {
      expect(byUrl('https://paren.example.com/page')?.originalUrl).toBe(
        'https://paren.example.com/page'
      );
    });

    test('treats www. URLs as https', () => {
      expect(byUrl('https://www.bare.example.com/docs')).toMatchObject({
        originalUrl: 'www.bare.example.com/docs',
      });
    });

    test('reports a URL that is both visible and clickable only once', () => {
      expect(links.filter((l) => l.url === 'https://both.example.com/doc')).toHaveLength(1);
    });
  });

  describe('Positions and context', () => {
    test('tracks page numbers across pages', () => {
      expect(new Set(links.map((l) => l.position.page))).toEqual(new Set([1, 2]));
      expect(byUrl('https://journal.example.org/articles/link-rot')?.position.page).toBe(2);
    });

    test('links are in document order with increasing offsets per page', () => {
      for (let i = 1; i < links.length; i++) {
        const prev = links[i - 1]!.position;
        const curr = links[i]!.position;
        expect(curr.page > prev.page || curr.offset > prev.offset).toBe(true);
      }
    });

    test('context includes the citation date for date extraction', () => {
      const link = byUrl('https://journal.example.org/articles/link-rot');
      expect(link?.context).toContain('(2023)');
      expect(link?.context).toContain('Retrieved 2023-06-15');
    });

    test('context is a single line of limited length', () => {
      for (const link of links) {
        expect(link.context).not.toMatch(/\n/);
        expect(link.context.length).toBeLessThanOrEqual(link.originalUrl.length + 2 * 50 + 10);
      }
    });
  });

  describe('Shape of results', () => {
    test('finds every link in the fixture exactly once', () => {
      expect(links.map((l) => l.url).sort()).toEqual(
        [
          'https://archive.org/web',
          'https://both.example.com/doc',
          'https://example.com/page?page=2',
          'https://journal.example.org/articles/link-rot',
          'https://paren.example.com/page',
          'https://plain.example.com/article',
          'https://www.bare.example.com/docs',
        ].sort()
      );
    });

    test('IDs are unique and follow link_N', () => {
      const ids = links.map((l) => l.id);
      expect(new Set(ids).size).toBe(ids.length);
      ids.forEach((id) => expect(id).toMatch(/^link_\d+$/));
    });

    test('accepts an ArrayBuffer and does not detach the caller’s buffer', async () => {
      const buf = await fixture('sample.pdf');
      const arrayBuffer = buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength);
      const again = await extractLinksFromPDF(arrayBuffer);

      expect(again).toHaveLength(links.length);
      expect(arrayBuffer.byteLength).toBe(buf.byteLength);
    });
  });

  describe('Errors', () => {
    test('returns an empty array for empty input', async () => {
      expect(await extractLinksFromPDF(new Uint8Array())).toEqual([]);
    });

    test('rejects password-protected PDFs with code ENCRYPTED', async () => {
      const error = await extractLinksFromPDF(await fixture('encrypted.pdf')).catch((e) => e);
      expect(error).toBeInstanceOf(PdfExtractionError);
      expect(error.code).toBe('ENCRYPTED');
      expect(error.message).toMatch(/password/i);
    });

    test('rejects files that are not PDFs with code PARSE_ERROR', async () => {
      const error = await extractLinksFromPDF(await fixture('corrupt.pdf')).catch((e) => e);
      expect(error).toBeInstanceOf(PdfExtractionError);
      expect(error.code).toBe('PARSE_ERROR');
    });

    test('an already-aborted signal throws TIMEOUT', async () => {
      const controller = new AbortController();
      controller.abort();
      const error = await extractLinksFromPDF(await fixture('sample.pdf'), {
        signal: controller.signal,
      }).catch((e: unknown) => e);
      expect(error).toBeInstanceOf(PdfExtractionError);
      expect((error as PdfExtractionError).code).toBe('TIMEOUT');
    });

    test('aborting during the parse throws TIMEOUT', async () => {
      const controller = new AbortController();
      const pending = extractLinksFromPDF(await fixture('sample.pdf'), {
        signal: controller.signal,
      }).catch((e: unknown) => e);
      controller.abort();
      const error = await pending;
      expect(error).toBeInstanceOf(PdfExtractionError);
      expect((error as PdfExtractionError).code).toBe('TIMEOUT');
    });

    test('more pages than maxPages throws TOO_MANY_PAGES', async () => {
      const error = await extractLinksFromPDF(await fixture('sample.pdf'), { maxPages: 2 }).catch(
        (e: unknown) => e
      );
      expect(error).toBeInstanceOf(PdfExtractionError);
      expect((error as PdfExtractionError).code).toBe('TOO_MANY_PAGES');
      expect((error as PdfExtractionError).message).toMatch(/3 pages/);
    });

    test('rejects random bytes with code PARSE_ERROR', async () => {
      const junk = new TextEncoder().encode('just some text, not a pdf');
      const error = await extractLinksFromPDF(junk).catch((e) => e);
      expect(error).toBeInstanceOf(PdfExtractionError);
      expect(error.code).toBe('PARSE_ERROR');
    });
  });

  describe('Citation dates', () => {
    test('sets citationDate from the surrounding text', () => {
      const citation = byUrl('https://journal.example.org/articles/link-rot');
      expect(citation?.citationDate?.toISOString()).toBe('2023-06-15T00:00:00.000Z');
    });

    test('leaves citationDate undefined when there is no date', () => {
      expect(byUrl('https://archive.org/web')?.citationDate).toBeUndefined();
    });
  });
});
